export async function createScene(engine, canvas, BABYLON) {
  console.clear();
  var scene = new BABYLON.Scene(engine);
  scene.useRightHandedSystem = true;
  scene.clearColor = new BABYLON.Color4(0, 0, 0);

  var camera = new BABYLON.ArcRotateCamera("Camera", Math.PI / 2, Math.PI / 2, 60, BABYLON.Vector3.Zero(), scene);
  camera.attachControl(canvas, true);

  var light = new BABYLON.HemisphericLight("light", new BABYLON.Vector3(0, 1, 0), scene);
  light.intensity = 0.7;

  const createTextParticles = (text, density, offset = new BABYLON.Vector3(0, 0, 0), font = "200px Arial", color = "white") => {
    const canvas = document.createElement("canvas");
    const ctx = canvas.getContext("2d");
    // canvas.width = engine.getRenderingCanvas().width;
    canvas.width = 2048;
    canvas.height = engine.getRenderingCanvas().height;

    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = color;
    ctx.font = font;
    ctx.textBaseline = "middle";
    ctx.textAlign = "center";
    ctx.fillText(text, canvas.width / 2, canvas.height / 2);

    const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);

    const particleSystem = new BABYLON.ParticleSystem("particles", 5000, scene);
    particleSystem.particleTexture = new BABYLON.Texture("https://www.babylonjs-playground.com/textures/flare.png", scene);

    particleSystem.emitter = new BABYLON.Vector3(0, 0, 0);
    particleSystem.minEmitBox = new BABYLON.Vector3(0, 0, 0);
    particleSystem.maxEmitBox = new BABYLON.Vector3(0, 0, 0);

    particleSystem.worldOffset = offset;

    particleSystem.minSize = 0.2;
    particleSystem.maxSize = 0.2;

    particleSystem.minLifeTime = Number.MAX_VALUE;
    particleSystem.maxLifeTime = Number.MAX_VALUE;

    particleSystem.manualEmitCount = Math.floor((canvas.width * canvas.height) / (density * density));

    particleSystem.updateSpeed = 0.01;

    particleSystem.start();

    let pointerPosition = new BABYLON.Vector2(0, 0);
    let hueOffset = 0;

    scene.onPointerObservable.add((pointerInfo) => {
      if (pointerInfo.type === BABYLON.PointerEventTypes.POINTERMOVE) {
        const event = pointerInfo.event;
        const rect = engine.getRenderingCanvas().getBoundingClientRect();
        pointerPosition.x = ((event.clientX - rect.left) / rect.width - 0.5) * canvas.width;
        pointerPosition.y = ((rect.height - (event.clientY - rect.top)) / rect.height - 0.5) * canvas.height;
      }
    });

    var advancedTexture = BABYLON.GUI.AdvancedDynamicTexture.CreateFullscreenUI("UI");

    var button = BABYLON.GUI.Button.CreateSimpleButton("Button", "Link");
    button.width = "150px";
    button.height = "40px";
    button.top = "40%";
    button.color = "Black";
    button.cornerRadius = 10;
    button.background = "Orange";
    button.onPointerUpObservable.add(function () {
      window.open("https://www.youtube.com/@_UNIT", "_blank");
    });
    advancedTexture.addControl(button);

    // 클릭된 지점이 파티클 영역 내에 있는지 확인하는 함수
    function isPointInsideBounds(point, emitter, minBox, maxBox) {
      return (
        point.x >= emitter.x + minBox.x &&
        point.x <= emitter.x + maxBox.x &&
        point.y >= emitter.y + minBox.y &&
        point.y <= emitter.y + maxBox.y &&
        point.z >= emitter.z + minBox.z &&
        point.z <= emitter.z + maxBox.z
      );
    }

    const hsvToRgb = (h, s, v) => {
      const c = v * s;
      const x = c * (1 - Math.abs(((h / 60) % 2) - 1));
      const m = v - c;

      let r, g, b;
      if (h < 60) [r, g, b] = [c, x, 0];
      else if (h < 120) [r, g, b] = [x, c, 0];
      else if (h < 180) [r, g, b] = [0, c, x];
      else if (h < 240) [r, g, b] = [0, x, c];
      else if (h < 300) [r, g, b] = [x, 0, c];
      else [r, g, b] = [c, 0, x];

      return new BABYLON.Color4(r + m, g + m, b + m, 1);
    };

    particleSystem.updateFunction = function (particles) {
      let particleIndex = 0;

      for (let y = 0; y < canvas.height; y += density) {
        for (let x = 0; x < canvas.width; x += density) {
          const pixelIndex = (y * canvas.width + x) * 4;

          if (imageData.data[pixelIndex + 3] > 50 && particleIndex < particles.length) {
            const particle = particles[particleIndex];
            particle.position.x = (x - canvas.width / 2) / 20;
            particle.position.y = (canvas.height / 2 - y) / 20;
            particle.position.z = 0;

            const hue = ((x / canvas.width) * 360 + hueOffset) % 360;
            particle.color = hsvToRgb(hue, 1, 1);

            const dx = particle.position.x * 20 - pointerPosition.x;
            const dy = particle.position.y * 20 - pointerPosition.y;

            const distance = Math.sqrt(dx * dx + dy * dy);
            if (distance < 100) {
              const force = (100 - distance) / 100;
              particle.position.x += force * dx * 0.03;
              particle.position.y += force * dy * 0.03;
            }

            particle.age = 0;
            particleIndex++;
          }
        }
      }

      for (let i = particleIndex; i < particles.length; i++) {
        const particle = particles[i];
        particle.position.x = Math.random() * 1000;
        particle.position.y = Math.random() * 1000;
        particle.position.z = Math.random() * 1000;
      }

      hueOffset = (hueOffset + 1) % 360;
    };

    return particleSystem;
  };

  createTextParticles("UNIT YOUTUBE", 4, new BABYLON.Vector3(0, 5, 0));
  createTextParticles("Subscribe", 4, new BABYLON.Vector3(0, -7, 0));

  return scene;
}
